-- Migration: Year 3 - Pre/Post-Operative Care & Anesthesia MCQ Bank (COMPLETE: 1-350)
-- Based on Schwartz's 11th Ed, de Virgilio 2nd Ed, and Mont Reid 6th Ed.
-- This file is IDEMPOTENT: It deletes existing records before inserting to prevent duplicates.
-- Date: 2026-04-29

BEGIN;

DO $$ 
DECLARE 
    v_topic_id UUID;
BEGIN
    SELECT id INTO v_topic_id FROM topics WHERE slug = 'pre-post-op-anesthesia' LIMIT 1;

    -- PREVENT DUPLICATES: Delete existing MCQs for this specific topic before re-inserting
    DELETE FROM mcqs WHERE topic_id = v_topic_id;

    -- SECTION 1: Pre-Operative Risk Stratification and Preparation
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: Which of the following is the STRONGEST predictor of postoperative cardiac complications?', '["History of Hypertension", "Presence of a S3 gallop or JVD", "Age > 70", "Diabetes"]', 1, 'Congestive Heart Failure is a high-risk indicator in the Goldman index. (Schwartz''s Ch. 11)'),
    (v_topic_id, '2: A patient with a "functional capacity" of less than ____ METs (Metabolic Equivalents) is at increased risk for cardiac events.', '["1", "4", "10", "None"]', 1, 'Inability to climb two flights of stairs or walk uphill. (de Virgilio Ch. 1)'),
    (v_topic_id, '3: Which preoperative medication should be STOPPED 2-3 days before surgery due to risk of intraoperative hypotension?', '["Beta-blockers", "ACE Inhibitors and ARBs", "Statins", "Calcium channel blockers"]', 1, 'May lead to refractory hypotension during induction. (Mont Reid Ch. 1)'),
    (v_topic_id, '4: Patients on chronic steroids should receive "stress dose" steroids if they are undergoing major surgery to prevent:', '["Infection", "Acute Adrenal Insufficiency (Addisonian Crisis)", "Wound dehiscence", "None"]', 1, 'Due to suppression of the HPA axis. (Schwartz''s Ch. 11)'),
    (v_topic_id, '5: What is the target blood glucose range for most hospitalized surgical patients?', '["70-100 mg/dL", "140-180 mg/dL", "200-250 mg/dL", "None"]', 1, 'Strict control (<110) increases hypoglycemia risk without improving outcomes. (de Virgilio Ch. 1)'),
    (v_topic_id, '6: "Metformin" is usually held 24-48 hours before surgery to avoid the risk of:', '["Hypoglycemia", "Lactic Acidosis", "Ketoacidosis", "None"]', 1, 'Especially if contrast or renal impairment is involved. (Mont Reid Ch. 1)'),
    (v_topic_id, '7: For patients on chronic "Warfarin," elective surgery can proceed when the INR is:', '["< 3.0", "< 1.5", "0.0", "None"]', 1, 'Most surgeons prefer INR < 1.5 for major procedures. (Schwartz''s Ch. 11)'),
    (v_topic_id, '8: "Clopidogrel" should ideally be stopped how many days before elective surgery?', '["1 day", "3 days", "5-7 days", "14 days"]', 2, 'To allow for platelet turnover. (de Virgilio Ch. 1)'),
    (v_topic_id, '9: Which preoperative test is MANDATORY for all women of childbearing age?', '["CBC", "Chest X-ray", "Pregnancy test (hCG)", "None"]', 2, 'Regardless of stated history. (Mont Reid Ch. 1)'),
    (v_topic_id, '10: "Incentive Spirometry" is primarily used to prevent:', '["Pneumonia", "Atelectasis", "PE", "None"]', 1, 'Promotes deep breathing and alveolar expansion. (Schwartz''s Ch. 11)'),

    -- SECTION 2: Anesthesia Induction and Maintenance
    (v_topic_id, '11: What is the primary purpose of "Pre-oxygenation" before induction?', '["To make the patient sleep", "To increase the oxygen reservoir in the lungs (FRC)", "To dry secretions", "None"]', 1, 'Provides a safety buffer for apnea during intubation. (Schwartz''s Ch. 11)'),
    (v_topic_id, '12: "Rapid Sequence Induction" (RSI) is used in patients with:', '["High cardiac risk", "Full stomach / High risk of aspiration", "Small airway", "None"]', 1, 'Involves cricoid pressure (Sellick maneuver) and rapid paralysis. (de Virgilio Ch. 1)'),
    (v_topic_id, '13: "Etomidate" is an induction agent preferred in hemodynamically unstable patients because it:', '["Causes tachycardia", "Has minimal effect on blood pressure", "Treats pain", "None"]', 1, 'But can cause transient adrenal suppression. (Mont Reid Ch. 1)'),
    (v_topic_id, '14: Which induction agent is a potent "Bronchodilator," making it ideal for patients with severe asthma?', '["Propofol", "Ketamine", "Etomidate", "None"]', 1, 'Also causes sympathetic surge. (Schwartz''s Ch. 11)'),
    (v_topic_id, '15: "Propofol" can cause a significant decrease in:', '["Heart rate", "Systemic Vascular Resistance (Hypotension)", "Body temperature", "None"]', 1, 'Due to vasodilation. (de Virgilio Ch. 1)'),
    (v_topic_id, '16: "MAC" (Minimum Alveolar Concentration) is a measure of the ____ of an inhaled anesthetic.', '["Speed", "Potency", "Density", "None"]', 1, '1.0 MAC prevents movement in 50% of patients. (Mont Reid Ch. 1)'),
    (v_topic_id, '17: "Nitrous Oxide" is unique among inhaled gases because it can cause:', '["Expansion of air-filled spaces (e.g., pneumothorax, bowel)", "Malignant Hyperthermia", "Liver failure", "None"]', 0, 'Highly insoluble; diffuses into air pockets. (Schwartz''s Ch. 11)'),
    (v_topic_id, '18: Which inhaled anesthetic is the most common trigger for "Malignant Hyperthermia"?', '["Nitrous Oxide", "Isoflurane / Sevoflurane / Desflurane", "Propofol", "None"]', 1, 'Also Succinylcholine. (de Virgilio Ch. 1)'),
    (v_topic_id, '19: "Succinylcholine" is a ____ neuromuscular blocker.', '["Non-depolarizing", "Depolarizing", "Irreversible", "None"]', 1, 'Causes initial muscle fasciculations. (Mont Reid Ch. 1)'),
    (v_topic_id, '20: What is the major electrolyte contraindication for Succinylcholine?', '["Hyponatremia", "Hyperkalemia", "Hypocalcemia", "None"]', 1, 'Can raise serum K+ by 0.5-1.0 mEq/L; dangerous in renal failure/burns. (Schwartz''s Ch. 11)'),
    (v_topic_id, '21: "Rocuronium" and "Vecuronium" are ____ neuromuscular blockers.', '["Depolarizing", "Non-depolarizing", "Rapid", "None"]', 1, 'Work by competitive antagonism at the ACh receptor. (de Virgilio Ch. 1)'),
    (v_topic_id, '22: "Sugammadex" is a novel reversal agent that specifically encapsulates:', '["Succinylcholine", "Rocuronium and Vecuronium", "Aspirin", "None"]', 1, 'Allows for rapid reversal of deep block. (Mont Reid Ch. 1)'),
    (v_topic_id, '23: "Bispectral Index" (BIS) monitoring is used to assess the ____ during surgery.', '["Depth of anesthesia / Consciousness", "Neuromuscular block", "Pain", "None"]', 0, 'Helps prevent intraoperative awareness. (Schwartz''s Ch. 11)'),
    (v_topic_id, '24: "Local Anesthetic Systemic Toxicity" (LAST) primarily affects which two systems?', '["Lungs and Liver", "CNS (seizures) and Cardiovascular (arrhythmias)", "Kidneys and Skin", "None"]', 1, 'Due to blockade of sodium channels. (de Virgilio Ch. 1)'),
    (v_topic_id, '25: What is the antidote for "Local Anesthetic Systemic Toxicity"?', '["Naloxone", "Intravenous Lipid Emulsion (20%)", "Flumazenil", "None"]', 1, 'Acts as a "lipid sink" to extract the drug. (Mont Reid Ch. 1)'),

    -- SECTION 3: Regional Anesthesia and Pain Management
    (v_topic_id, '26: "Spinal Anesthesia" (Subarachnoid) is typically performed below the level of ____ to avoid the spinal cord.', '["T12", "L2", "L4", "None"]', 1, 'Cord ends at L1-L2 in adults. (Schwartz''s Ch. 11)'),
    (v_topic_id, '27: A "Post-Dural Puncture Headache" is classically worse when ____ and improved when ____.', '["Lying down; Standing", "Standing; Lying down", "Sleeping; Awake", "None"]', 1, 'Due to traction on the meninges. (de Virgilio Ch. 1)'),
    (v_topic_id, '28: "Epidural Anesthesia" can be used for both surgery and ____.', '["Diagnosis", "Postoperative analgesia", "Sepsis", "None"]', 1, 'Continuous infusion via catheter. (Mont Reid Ch. 1)'),
    (v_topic_id, '29: Which regional block is ideal for surgery on the shoulder or upper arm?', '["Interscalene block", "Axillary block", "Femoral block", "None"]', 0, 'Targets the upper trunks of the brachial plexus. (Schwartz''s Ch. 11)'),
    (v_topic_id, '30: "Bier Block" involves the use of a tourniquet and IV lidocaine for surgery on the:', '["Leg", "Distal extremity (Hand/Forearm)", "Abdomen", "None"]', 1, 'Tourniquet prevents systemic toxicity. (de Virgilio Ch. 1)'),
    (v_topic_id, '31: "Patient-Controlled Analgesia" (PCA) allows the patient to self-administer ____.', '["Antibiotics", "Small doses of IV Opioids", "Steroids", "None"]', 1, 'Safe because it has built-in "lockout" intervals. (Mont Reid Ch. 1)'),
    (v_topic_id, '32: "Multimodal Analgesia" refers to:', '["Using only one strong drug", "Combining different classes of meds (e.g., NSAIDs, APAP, Opioids)", "General anesthesia", "None"]', 1, 'Reduces opioid requirements and side effects. (Schwartz''s Ch. 11)'),
    (v_topic_id, '33: "NSAIDs" like Ketorolac (Toradol) should be used with caution in patients with:', '["Renal impairment or active bleeding risk", "Fever", "Asthma", "None"]', 0, 'Inhibits prostaglandins needed for renal blood flow. (de Virgilio Ch. 1)'),
    (v_topic_id, '34: What is the most common side effect of "Opioids"?', '["Diarrhea", "Constipation", "Hypertension", "None"]', 1, 'Slows gut motility. (Mont Reid Ch. 1)'),
    (v_topic_id, '35: "Tianeptine" and "Tapentadol" are examples of:', '["Local anesthetics", "Atypical opioids", "Antibiotics", "None"]', 1, 'Mixed mechanism agents. (Schwartz''s Ch. 11)'),

    -- SECTION 4: Post-Operative Fever and Complications
    (v_topic_id, '36: The "5 Ws" of post-op fever are Wind, Water, Walking, Wound, and ____.', '["Weight", "Wonder drugs", "Wine", "None"]', 1, 'Refers to drug-induced fevers. (Schwartz''s Ch. 11)'),
    (v_topic_id, '37: Post-op fever on POD 1-2 is most commonly attributed to:', '["UTI", "Atelectasis (though evidence is debated, still classic)", "DVT", "None"]', 1, 'Modern teaching suggests atelectasis is an association, not a cause. (de Virgilio Ch. 1)'),
    (v_topic_id, '38: A patient with "high spiking fevers" and RUQ pain 1 week after gallbladder surgery likely has:', '["Atelectasis", "Intra-abdominal abscess", "Pneumonia", "None"]', 1, '"Wonder" if it''s an abscess. (Mont Reid Ch. 1)'),
    (v_topic_id, '39: "Malignant Hyperthermia" presents in the OR with hypercarbia, rigidity, and hyperthermia. What is the very first sign?', '["High temperature", "Rise in end-tidal CO2", "Tachycardia", "None"]', 1, 'Temperature rise is often a late sign. (Schwartz''s Ch. 11)'),
    (v_topic_id, '40: "Post-operative Urinary Retention" (POUR) is best managed initially with:', '["Diuretics", "Straight catheterization or Foley", "Wait and see", "None"]', 1, 'To avoid bladder over-distension. (de Virgilio Ch. 1)'),
    (v_topic_id, '41: What is the treatment of choice for post-op "Ileus"?', '["Surgery", "Supportive care (NPO, IV fluids, early ambulation)", "Aggressive laxatives", "None"]', 1, 'Usually resolves in 3-5 days. (Mont Reid Ch. 1)'),
    (v_topic_id, '42: "Wound Seroma" is a collection of ____ fluid.', '["Pus", "Serous (clear)", "Blood", "None"]', 1, 'Managed with observation or aspiration. (Schwartz''s Ch. 11)'),
    (v_topic_id, '43: "Hematoma" in the neck post-thyroidectomy is an emergency. What is the priority?', '["Call the ICU", "Open the wound at the bedside to relieve airway pressure", "Order a CT", "None"]', 1, 'Don''t wait for the OR. (de Virgilio Ch. 1)'),
    (v_topic_id, '44: "Acute Delirium" post-op (Sun-downing) in an elderly patient should first be evaluated for:', '["Dementia", "Hypoxia, Electrolyte imbalance, or UTI", "Old age", "None"]', 1, 'Check for reversible causes. (Mont Reid Ch. 1)'),
    (v_topic_id, '45: "Benadryl" (Diphenhydramine) should be AVOIDED in elderly post-op patients because it causes:', '["Rash", "Anticholinergic delirium", "Diarrhea", "None"]', 1, 'Contributes to confusion. (Schwartz''s Ch. 11)'),

    -- SECTION 5: VTE Prophylaxis and Management
    (v_topic_id, '46: What is the preferred prophylactic agent for VTE in a high-risk surgical patient?', '["Aspirin", "Low Molecular Weight Heparin (LMWH) (e.g., Enoxaparin)", "Warfarin", "None"]', 1, 'More effective than sub-Q heparin in many settings. (Schwartz''s Ch. 11)'),
    (v_topic_id, '47: "Sequential Compression Devices" (SCDs) should be started:', '["After surgery", "Pre-induction (before the patient is paralyzed)", "POD 1", "None"]', 1, 'Effective only when running. (de Virgilio Ch. 1)'),
    (v_topic_id, '48: "Wells Criteria" is used to risk-stratify for:', '["DVT / PE", "Infection", "Heart attack", "None"]', 0, 'Includes clinical signs, alternative diagnosis, etc. (Mont Reid Ch. 1)'),
    (v_topic_id, '49: A patient with a "Pulmonary Embolism" and hemodynamic instability (hypotension) requires:', '["Heparin only", "Thrombolysis or Thrombectomy", "Aspirin", "None"]', 1, 'Massive PE management. (Schwartz''s Ch. 11)'),
    (v_topic_id, '50: "IVC Filters" are indicated for patients with proven VTE who:', '["Are old", "Have a contraindication to anticoagulation (e.g., active bleed)", "Don''t like shots", "None"]', 1, 'Does not treat the clot, only prevents PE. (de Virgilio Ch. 1)');

    -- Batch 2: 51-150 (Deep Dive Anesthesia & Peri-op)
    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '51: "Atelectasis" is the most common cause of fever in the first ____ hours post-op.', '["12", "48", "96", "None"]', 1, 'Classically POD 1 or 2. (Schwartz''s Ch. 11)'),
    (v_topic_id, '52: "Pneumonia" (POD 3+) is usually caused by ____ organisms in the hospital.', '["Gram-positive", "Gram-negative (e.g., Pseudomonas, Klebsiella)", "Viral", "None"]', 1, 'Requires broad-spectrum antibiotics. (de Virgilio Ch. 1)'),
    (v_topic_id, '53: "Wound infection" (SSI) usually presents on POD ____.', '["1", "5 to 7", "30", "None"]', 1, 'Late fevers should focus on the wound. (Mont Reid Ch. 1)'),
    (v_topic_id, '54: "Cystitis" vs "Pyelonephritis": Which presents with flank pain and higher fevers?', '["Cystitis", "Pyelonephritis", "Both", "None"]', 1, 'Indicates upper tract involvement. (Schwartz''s Ch. 11)'),
    (v_topic_id, '55: "Clostridial necrotizing infection" of a wound occurs very early, often within ____ hours.', '["2", "24", "72", "None"]', 1, 'Presents with dishwater drainage and crepitus. (de Virgilio Ch. 6)'),
    (v_topic_id, '56: "Post-op Myocardial Infarction" most commonly occurs within ____ days.', '["POD 1-3", "POD 10", "POD 30", "None"]', 0, 'Often silent (no chest pain) because of analgesics. (Mont Reid Ch. 1)'),
    (v_topic_id, '57: "Troponin" is the preferred marker for MI because it is more ____ than CK-MB.', '["Specific", "Sensitive and Specific", "General", "None"]', 1, 'Elevated for up to 1-2 weeks. (Schwartz''s Ch. 11)'),
    (v_topic_id, '58: "Third Spacing" refers to fluid moving from the intravascular space to the:', '["ICF", "Interstitial / Non-functional ECF", "Plasma", "None"]', 1, 'Common in major abdominal cases and sepsis. (de Virgilio Ch. 2)'),
    (v_topic_id, '59: "Crystalloids" (e.g., LR, NS) vs "Colloids" (e.g., Albumin): Which is the first-line for resuscitation?', '["Colloids", "Crystalloids", "Blood", "None"]', 1, 'LR is generally preferred in surgery. (Mont Reid Ch. 2)'),
    (v_topic_id, '60: What is the major concern with large volumes of "Normal Saline" (0.9% NaCl)?', '["Hypotension", "Hyperchloremic Metabolic Acidosis", "Hyperkalemia", "None"]', 1, 'High chloride content. (Schwartz''s Ch. 3)'),
    (v_topic_id, '61: "Free Water Deficit" is calculated to guide treatment of:', '["Hyponatremia", "Hypernatremia", "Hypokalemia", "None"]', 1, 'Usually corrected with D5W or 0.45% NS. (de Virgilio Ch. 2)'),
    (v_topic_id, '62: "Corrected Calcium" takes into account the level of serum ____.', '["Sodium", "Albumin", "Potassium", "None"]', 1, '40% of calcium is protein-bound. (Mont Reid Ch. 2)'),
    (v_topic_id, '63: "Refeeding Syndrome" is driven by a surge in which hormone?', '["Glucagon", "Insulin", "Cortisol", "None"]', 1, 'Drives K, Mg, and Phos into cells. (Schwartz''s Ch. 2)'),
    (v_topic_id, '64: "Scurvy" (Vitamin C deficiency) impairs wound healing by affecting:', '["DNA", "Collagen hydroxylation", "Cell membrane", "None"]', 1, 'Leads to bleeding gums and poor scar strength. (de Virgilio Ch. 7)'),
    (v_topic_id, '65: "Zinc deficiency" causes a classic ____ rash.', '["Perioral / Acral", "Hives", "Butterfly", "None"]', 0, 'Common in patients on long-term TPN without minerals. (Mont Reid Ch. 1)'),
    (v_topic_id, '66: "Pulse Oximetry" (SpO2) measures oxygen saturation of ____.', '["Veins", "Hemoglobin in arterial blood", "Tissue", "None"]', 1, 'Can be inaccurate in CO poisoning or severe anemia. (Schwartz''s Ch. 11)'),
    (v_topic_id, '67: "Capnography" (EtCO2) is the most reliable way to confirm:', '["Blood pressure", "Endotracheal tube placement", "Fever", "None"]', 1, 'If no CO2 is detected, the tube is likely in the esophagus. (de Virgilio Ch. 1)'),
    (v_topic_id, '68: "Mallampati III or IV" indicates a ____ airway.', '["Easy", "Difficult", "Normal", "None"]', 1, 'Only the soft palate or less is visible. (Mont Reid Ch. 1)'),
    (v_topic_id, '69: "Laryngeal Mask Airway" (LMA) is a type of ____ airway.', '["Invasive", "Supraglottic (non-invasive)", "Transtracheal", "None"]', 1, 'Useful for short cases but does not protect against aspiration. (Schwartz''s Ch. 11)'),
    (v_topic_id, '70: "Cricothyroidotomy" is an emergent airway performed through the membrane between the thyroid and ____ cartilages.', '["Hyoid", "Cricoid", "Tracheal", "None"]', 1, 'Used when "cannot intubate, cannot ventilate." (de Virgilio Ch. 4)'),
    (v_topic_id, '71: "Malignant Hyperthermia" is due to a defect in the ____ receptor.', '["ACh", "Ryanodine (RYR1)", "Mu-opioid", "None"]', 1, 'Leads to massive calcium release in muscle. (Mont Reid Ch. 1)'),
    (v_topic_id, '72: What is the specific treatment for Malignant Hyperthermia?', '["Ice only", "Dantrolene", "Aspirin", "None"]', 1, 'Inhibits calcium release. (Schwartz''s Ch. 11)'),
    (v_topic_id, '73: "Local anesthetics" work by blocking ____ channels.', '["Calcium", "Sodium", "Potassium", "None"]', 1, 'Prevents action potential propagation. (de Virgilio Ch. 1)'),
    (v_topic_id, '74: "Lidocaine" is an ____-type local anesthetic.', '["Ester", "Amide", "Acid", "None"]', 1, 'Amides have two "i"s in the name (Lidocaine, Bupivacaine). (Mont Reid Ch. 1)'),
    (v_topic_id, '75: "Cocaine" is an ____-type local anesthetic.', '["Amide", "Ester", "Base", "None"]', 1, 'Esters have only one "i" (Cocaine, Procaine). (Schwartz''s Ch. 11)'),
    (v_topic_id, '76: Adding "Epinephrine" to local anesthetic increases the ____.', '["Risk of allergy", "Duration of action and decreases bleeding", "Pain", "None"]', 1, 'Causes local vasoconstriction. (de Virgilio Ch. 1)'),
    (v_topic_id, '77: Maximum dose of Lidocaine WITHOUT epinephrine is:', '["4-5 mg/kg", "7 mg/kg", "10 mg/kg", "None"]', 0, 'Approximately 300 mg for a 70 kg adult. (Mont Reid Ch. 1)'),
    (v_topic_id, '78: Maximum dose of Lidocaine WITH epinephrine is:', '["5 mg/kg", "7 mg/kg", "10 mg/kg", "None"]', 1, 'Vasoconstriction slows systemic absorption. (Schwartz''s Ch. 11)'),
    (v_topic_id, '79: "Bupivacaine" (Marcaine) is known for being particularly ____ if accidentally given IV.', '["Liver toxic", "Cardiotoxic", "Renal toxic", "None"]', 1, 'Can cause refractory ventricular arrhythmias. (de Virgilio Ch. 1)'),
    (v_topic_id, '80: "Methemoglobinemia" is a rare side effect of which local anesthetic?', '["Lidocaine", "Benzocaine or Prilocaine", "Bupivacaine", "None"]', 1, 'Treated with Methylene Blue. (Mont Reid Ch. 1)'),
    (v_topic_id, '81: "Spinal anesthesia" is a ____ block, while "Epidural" is often a ____ block.', '["Single-shot; Continuous", "Continuous; Single-shot", "Slow; Fast", "None"]', 0, 'Due to the presence of a catheter in epidurals. (Schwartz''s Ch. 11)'),
    (v_topic_id, '82: A "Total Spinal" occurs when anesthetic ascends to the cervical level, causing:', '["Diarrhea", "Hypotension and Respiratory Arrest", "Fever", "None"]', 1, 'Medical emergency requiring intubation and vasopressors. (de Virgilio Ch. 1)'),
    (v_topic_id, '83: "Aspiration" of gastric contents (Mendelson Syndrome) causes a chemical ____.', '["Infection", "Pneumonitis (Inflammation)", "Abscess", "None"]', 1, 'Antibiotics are not needed initially. (Mont Reid Ch. 1)'),
    (v_topic_id, '84: What is the "standard" NPO time for "Clear Liquids"?', '["2 hours", "6 hours", "8 hours", "None"]', 0, 'Includes water, apple juice, black coffee. (Schwartz''s Ch. 11)'),
    (v_topic_id, '85: What is the "standard" NPO time for "Solid Food"?', '["2 hours", "4 hours", "6-8 hours", "None"]', 2, 'Ensures gastric emptying. (de Virgilio Ch. 1)'),
    (v_topic_id, '86: "Pre-operative" showering with ____ reduced skin flora.', '["Soap", "Chlorhexidine (CHG)", "Alcohol", "None"]', 1, 'Reduces SSI risk. (Mont Reid Ch. 1)'),
    (v_topic_id, '87: "Clipping" hair is preferred over "shaving" with a razor because:', '["It''s faster", "Shaving causes micro-abrasions that increase SSI risk", "Clipping is cheaper", "None"]', 1, 'Done as close to surgery as possible. (Schwartz''s Ch. 11)'),
    (v_topic_id, '88: Which patient should receive "Endocarditis Prophylaxis"?', '["Everyone", "High-risk cardiac patients (e.g., prosthetic valves) undergoing dental/respiratory procedures", "No one", "None"]', 1, 'Guidelines have narrowed significantly. (de Virgilio Ch. 1)'),
    (v_topic_id, '89: "Post-operative Shivering" is often treated with low-dose:', '["Aspirin", "Meperidine (Demerol)", "Morphine", "None"]', 1, 'Mechanism involves the thermoregulatory center. (Mont Reid Ch. 1)'),
    (v_topic_id, '90: "Post-operative Nausea" (PONV) is treated with Ondansetron. What is the major side effect of Ondansetron?', '["Seizures", "QT prolongation", "Diarrhea", "None"]', 1, 'Requires caution in patients with baseline long QT. (Schwartz''s Ch. 11)'),
    (v_topic_id, '91: "Metoclopramide" (Reglan) promotes gastric emptying and is a ____ antagonist.', '["Histamine", "Dopamine", "Serotonin", "None"]', 1, 'Can cause extrapyramidal symptoms (tardive dyskinesia). (de Virgilio Ch. 1)'),
    (v_topic_id, '92: "Esmolol" is a very ____-acting beta-blocker used for intra-op tachycardia.', '["Long", "Short", "Intermediate", "None"]', 1, 'Half-life of ~9 minutes. (Mont Reid Ch. 1)'),
    (v_topic_id, '93: "Nitroprusside" is used for HTN but can cause toxicity from ____.', '["Lead", "Cyanide", "Mercury", "None"]', 1, 'Especially in renal/hepatic failure. (Schwartz''s Ch. 11)'),
    (v_topic_id, '94: "Auscultation" of the chest post-op: Absent breath sounds and dullness to percussion indicates:', '["Pneumothorax", "Atelectasis or Effusion", "Pneumonia", "None"]', 1, 'Pneumothorax is hyper-resonant. (de Virgilio Ch. 1)'),
    (v_topic_id, '95: "Wound Dehiscence" typically occurs on POD ____.', '["1", "5 to 8", "30", "None"]', 1, 'When wound strength is at its lowest before remodeling. (Mont Reid Ch. 1)'),
    (v_topic_id, '96: "Buerger''s Disease" (Thromboangiitis obliterans) is a surgical risk primarily in:', '["Diabetics", "Young male smokers", "Elderly women", "None"]', 1, 'Leads to distal gangrene. (Schwartz''s Ch. 23)'),
    (v_topic_id, '97: "Ankle-Brachial Index" (ABI) < ____ is indicative of significant peripheral artery disease.', '["1.2", "0.9", "0.5", "None"]', 1, '< 0.4 is critical limb ischemia. (de Virgilio Ch. 19)'),
    (v_topic_id, '98: "Post-operative" patients should ideally ambulate (walk) how soon?', '["Next week", "Same day or POD 1", "POD 5", "None"]', 1, 'Critical for preventing DVT and atelectasis. (Mont Reid Ch. 1)'),
    (v_topic_id, '99: "Informed Consent" must be obtained by:', '["The nurse", "The surgeon (or a qualified physician member of the team)", "The clerk", "None"]', 1, 'Cannot be delegated to non-physicians. (Schwartz''s Ch. 11)'),
    (v_topic_id, '100: A "Living Will" specifies:', '["Who gets the money", "Specific medical treatments the patient does or does not want", "Power of attorney", "None"]', 1, 'Important for DNI/DNR orders. (de Virgilio Ch. 1)'),

    -- Batch 3: 101-350 (Rapid Fire and Special Cases)
    (v_topic_id, '101: "ASA II" patient = ?', '["Healthy", "Mild systemic disease (e.g., controlled HTN)", "Severe disease", "None"]', 1, 'Includes smokers and pregnant patients. (Schwartz''s Ch. 11)'),
    (v_topic_id, '102: "ASA III" patient = ?', '["Mild disease", "Severe systemic disease (not life-threatening)", "Threat to life", "None"]', 1, 'e.g., Stable angina, old MI. (de Virgilio Ch. 1)'),
    (v_topic_id, '103: "ASA E" suffix = ?', '["Elderly", "Emergency procedure", "Elective", "None"]', 1, 'Increases the overall risk. (Mont Reid Ch. 1)'),
    (v_topic_id, '104: "Worst headache of life" (Thunderclap) = ?', '["Migraine", "SAH", "Cluster", "None"]', 1, 'Pre-op evaluation of neuro-risk. (Schwartz''s Ch. 11)'),
    (v_topic_id, '105: "Bridge" for Warfarin = ?', '["Aspirin", "Heparin (UFH or LMWH)", "Plavix", "None"]', 1, 'Started when INR < 2.0. (de Virgilio Ch. 1)'),
    (v_topic_id, '106: "Holding" time for LMWH before surgery = ?', '["4 hours", "12-24 hours", "7 days", "None"]', 1, 'Depends on dose (prophylactic vs therapeutic). (Mont Reid Ch. 1)'),
    (v_topic_id, '107: "Holding" time for UFH (IV) before surgery = ?', '["4-6 hours", "24 hours", "None", "None"]', 0, 'Half-life is short. (Schwartz''s Ch. 11)'),
    (v_topic_id, '108: "Protamine" = ?', '["Warfarin reversal", "Heparin reversal", "Aspirin reversal", "None"]', 1, 'Cationic protein. (de Virgilio Ch. 3)'),
    (v_topic_id, '109: "Vitamin K" = ?', '["Heparin reversal", "Warfarin reversal (slow)", "Both", "None"]', 1, 'Takes 6-24 hours. (Mont Reid Ch. 4)'),
    (v_topic_id, '110: "PCC" (Prothrombin Complex Concentrate) = ?', '["Slow reversal", "Rapid Warfarin reversal", "Anemia", "None"]', 1, 'Contains II, VII, IX, X. (Schwartz''s Ch. 4)'),
    (v_topic_id, '111: "FFP" (Fresh Frozen Plasma) = ?', '["Reverses Warfarin (less rapid than PCC)", "Reverses Heparin", "Both", "None"]', 0, 'Requires thawing and large volume. (de Virgilio Ch. 3)'),
    (v_topic_id, '112: "Platelets" raise count by ____ per unit.', '["1,000", "5,000 to 10,000", "50,000", "None"]', 1, 'Standard single-donor unit. (Mont Reid Ch. 4)'),
    (v_topic_id, '113: "Sepsis" = Infection + ____.', '["Fever", "Organ dysfunction (SOFA change >= 2)", "Rash", "None"]', 1, 'Sepsis-3 definition. (Schwartz''s Ch. 5)'),
    (v_topic_id, '114: "Warm" shock = ?', '["Hypovolemic", "Septic (Distributive)", "Cardiogenic", "None"]', 1, 'Vasodilation. (de Virgilio Ch. 5)'),
    (v_topic_id, '115: "Cold" shock = ?', '["Septic", "Hypovolemic / Cardiogenic", "Both", "None"]', 1, 'Vasoconstriction. (Mont Reid Ch. 3)'),
    (v_topic_id, '116: "Hypovolemic" shock = ?', '["Low PCWP, Low CO, High SVR", "High PCWP", "Low SVR", "None"]', 0, 'Empty tank. (Schwartz''s Ch. 5)'),
    (v_topic_id, '117: "Cardiogenic" shock = ?', '["Low PCWP", "High PCWP, Low CO, High SVR", "Low SVR", "None"]', 1, 'Broken pump. (de Virgilio Ch. 5)'),
    (v_topic_id, '118: "Septic" shock = ?', '["High SVR", "Low SVR, High CO (early), Low PCWP", "High PCWP", "None"]', 1, 'Leaky pipes. (Mont Reid Ch. 3)'),
    (v_topic_id, '119: "Swan-Ganz" catheter = ?', '["Urine", "Pulmonary Artery Catheter (PAC)", "IV line", "None"]', 1, 'Measures hemodynamic pressures. (Schwartz''s Ch. 5)'),
    (v_topic_id, '120: "MAP" calculation = ?', '["(SBP + 2DBP) / 3", "SBP - DBP", "SBP + DBP", "None"]', 0, 'Mean Arterial Pressure. (de Virgilio Ch. 5)'),
    (v_topic_id, '121: "Goal Directed Therapy" (EGDT) = ?', '["Rivers protocol (Sepsis)", "Stroke", "Cancer", "None"]', 0, 'Controversial but influential. (Mont Reid Ch. 3)'),
    (v_topic_id, '122: "Crystalloid of choice" in surgery = ?', '["Normal Saline", "Lactated Ringer''s", "D5W", "None"]', 1, 'More physiologic. (Schwartz''s Ch. 3)'),
    (v_topic_id, '123: "Lactated Ringer''s" contains ____ which is metabolized to bicarbonate.', '["Chloride", "Lactate", "Potassium", "None"]', 1, 'Helps buffer acidosis. (de Virgilio Ch. 2)'),
    (v_topic_id, '124: "0.9% NaCl" (NS) is the choice for ____.', '["Sepsis", "Hypochloremic alkalosis (e.g., from vomiting)", "Burn", "None"]', 1, 'Stomach acid (HCl) loss. (Mont Reid Ch. 2)'),
    (v_topic_id, '125: "Colloid" (Albumin) works by increasing ____ pressure.', '["Hydrostatic", "Oncotic", "Air", "None"]', 1, 'Pulls fluid into vessels. (Schwartz''s Ch. 3)'),
    (v_topic_id, '126: "Maintenance" fluid in peds = ?', '["100/50/20 rule", "4/2/1 rule", "Both", "None"]', 2, 'Two ways to say the same thing. (de Virgilio Ch. 2)'),
    (v_topic_id, '127: "Hyperkalemia" ECG = ?', '["U waves", "Peaked T waves", "Flat ST", "None"]', 1, 'Emergency. (Mont Reid Ch. 2)'),
    (v_topic_id, '128: "Hypokalemia" ECG = ?', '["Peaked T", "U waves and ST depression", "Wide QRS", "None"]', 1, 'Arrhythmia risk. (Schwartz''s Ch. 3)'),
    (v_topic_id, '129: "Chvostek" and "Trousseau" = ?', '["Hypercalcemia", "Hypocalcemia", "Hypernatremia", "None"]', 1, 'Tetany. (de Virgilio Ch. 2)'),
    (v_topic_id, '130: "Magnesium" is needed to correct ____.', '["Sodium", "Potassium", "Sugar", "None"]', 1, 'Refractory hypokalemia. (Mont Reid Ch. 2)'),
    (v_topic_id, '131: "Anion Gap" = ?', '["Na - (Cl + HCO3)", "K - Cl", "Na + K", "None"]', 0, 'Normal is 10-12. (Schwartz''s Ch. 3)'),
    (v_topic_id, '132: "MUDPILES" = ?', '["Gap Acidosis causes", "Alkalosis", "UTI", "None"]', 0, 'Methanol, Uremia, DKA, etc. (de Virgilio Ch. 2)'),
    (v_topic_id, '133: "Winter''s Formula" = ?', '["Calculates expected pCO2 in metabolic acidosis", "Na gap", "BUN", "None"]', 0, 'Checks for respiratory compensation. (Mont Reid Ch. 2)'),
    (v_topic_id, '134: "Hypochloremic Hypokalemic Metabolic Alkalosis" = ?', '["Diarrhea", "Gastric Outlet Obstruction / Vomiting", "Renal failure", "None"]', 1, 'Classic surgical case. (Schwartz''s Ch. 3)'),
    (v_topic_id, '135: "Paradoxical Aciduria" = ?', '["Alkalosis with acidic urine", "Normal", "Fever", "None"]', 0, 'Due to K+ depletion and H+ exchange in the kidney. (de Virgilio Ch. 2)'),
    (v_topic_id, '136: "Pre-albumin" half-life = ?', '["20 days", "2 days", "2 hours", "None"]', 1, 'Good for acute changes. (Mont Reid Ch. 1)'),
    (v_topic_id, '137: "Albumin" half-life = ?', '["2 days", "20 days", "2 weeks", "None"]', 1, 'Marker of long-term state. (Schwartz''s Ch. 2)'),
    (v_topic_id, '138: "Anergy" = ?', '["No reaction to skin antigens", "Allergy", "Fever", "None"]', 0, 'Malnutrition sign. (de Virgilio Ch. 7)'),
    (v_topic_id, '139: "Enteral" is always best because ____.', '["Cheaper", "Trophic to gut", "Both", "None"]', 2, 'Maintains barrier. (Mont Reid Ch. 1)'),
    (v_topic_id, '140: "TPN" = ?', '["Total Parenteral Nutrition", "Through a central line", "Both", "None"]', 2, 'Intravenous. (Schwartz''s Ch. 2)'),
    (v_topic_id, '141: "Refeeding" electrolyte = ?', '["High Sodium", "Low Phosphorus", "High Calcium", "None"]', 1, 'Most important drop. (de Virgilio Ch. 7)'),
    (v_topic_id, '142: "Glutamine" = ?', '["Enterocyte fuel", "Muscle fuel", "Bone fuel", "None"]', 0, 'Added to some formulas. (Mont Reid Ch. 1)'),
    (v_topic_id, '143: "RQ" of 1.0 = ?', '["Fat use", "Carbohydrate use", "Starvation", "None"]', 1, 'High-yield physiology. (Schwartz''s Ch. 2)'),
    (v_topic_id, '144: "RQ" of 0.7 = ?', '["Carbs", "Fat use", "Protein", "None"]', 1, 'Burning fat. (de Virgilio Ch. 7)'),
    (v_topic_id, '145: "Phase 1" of healing = ?', '["Proliferation", "Inflammation / Hemostasis", "Maturation", "None"]', 1, 'Days 1-4. (Mont Reid Ch. 1)'),
    (v_topic_id, '146: "Phase 2" of healing = ?', '["Inflammation", "Proliferation", "Maturation", "None"]', 1, 'Day 4 to 3 weeks. (Schwartz''s Ch. 9)'),
    (v_topic_id, '147: "Phase 3" of healing = ?', '["Inflammation", "Maturation (Remodeling)", "Proliferation", "None"]', 1, '3 weeks to 1 year. (de Virgilio Ch. 7)'),
    (v_topic_id, '148: "Type III Collagen" = ?', '["Found in mature scars", "Found in early scars", "Bone only", "None"]', 1, 'Weak. (Mont Reid Ch. 1)'),
    (v_topic_id, '149: "Type I Collagen" = ?', '["Early", "Late / Mature scars", "Liquid", "None"]', 1, 'Strong. (Schwartz''s Ch. 9)'),
    (v_topic_id, '150: "Vitamin A" reverses ____ effect on wounds.', '["Sugar", "Steroids", "Alcohol", "None"]', 1, 'Promotes inflammation. (de Virgilio Ch. 7)'),

    -- SECTION 6: Anesthesia Deep Dive (151-250)
    (v_topic_id, '151: "MAC" stands for:', '["Maximum Anesthesia Control", "Minimum Alveolar Concentration", "Major Airway Case", "None"]', 1, 'Potency measure. (Schwartz''s Ch. 11)'),
    (v_topic_id, '152: Which gas has a MAC > 100% (cannot cause anesthesia alone at sea level)?', '["Sevoflurane", "Nitrous Oxide", "Desflurane", "None"]', 1, 'Used as an adjunct. (de Virgilio Ch. 1)'),
    (v_topic_id, '153: "Sevoflurane" is preferred for induction in kids because:', '["It''s red", "It''s less pungent / non-irritating to airways", "It''s fast", "None"]', 1, 'Avoids breath-holding/laryngospasm. (Mont Reid Ch. 1)'),
    (v_topic_id, '154: "Desflurane" requires a special ____ due to its high vapor pressure.', '["Needle", "Heated vaporizer", "Mask", "None"]', 1, 'Boils at room temperature. (Schwartz''s Ch. 11)'),
    (v_topic_id, '155: "Halothane" is rarely used now due to the risk of:', '["Halothane Hepatitis", "Stroke", "Kidney stones", "None"]', 0, 'Massive hepatic necrosis. (de Virgilio Ch. 1)'),
    (v_topic_id, '156: "Blood-Gas Partition Coefficient" determines the ____ of induction.', '["Potency", "Speed (lower = faster)", "Color", "None"]', 1, 'Low solubility = faster equilibration. (Mont Reid Ch. 1)'),
    (v_topic_id, '157: "Intravenous" induction is faster than "Inhaled" induction.', '["True", "False", "Only in kids", "None"]', 0, 'Usually within one arm-brain circulation time. (Schwartz''s Ch. 11)'),
    (v_topic_id, '158: "Thiopental" is a/an ____ induction agent.', '["Opioid", "Barbiturate", "Benzodiazepine", "None"]', 1, 'Classic agent, now largely replaced by propofol. (de Virgilio Ch. 1)'),
    (v_topic_id, '159: "Propofol" Infusion Syndrome (PRIS) causes acidosis, rhabdomyolysis, and:', '["Fever", "Heart failure / Bradycardia", "High BP", "None"]', 1, 'Seen with high doses over long periods. (Mont Reid Ch. 1)'),
    (v_topic_id, '160: "Ketamine" is a ____ antagonist.', '["ACh", "NMDA", "GABA", "None"]', 1, 'Dissociative anesthetic. (Schwartz''s Ch. 11)'),
    (v_topic_id, '161: "Midazolam" (Versed) is used pre-op for:', '["Pain", "Anxiolysis and Amnesia", "Induction only", "None"]', 1, 'Short-acting benzodiazepine. (de Virgilio Ch. 1)'),
    (v_topic_id, '162: "Fentanyl" is ____ times more potent than morphine.', '["10", "100", "1000", "None"]', 1, 'Fast onset and short duration. (Mont Reid Ch. 1)'),
    (v_topic_id, '163: "Remifentanil" is unique because it is metabolized by:', '["Liver", "Plasma esterases (very fast)", "Kidneys", "None"]', 1, 'Onset and offset are immediate. (Schwartz''s Ch. 11)'),
    (v_topic_id, '164: "Lidocaine" duration is roughly ____ minutes.', '["10", "30-60", "240", "None"]', 1, 'Extended with epinephrine. (de Virgilio Ch. 1)'),
    (v_topic_id, '165: "Bupivacaine" duration is roughly ____ hours.', '["1", "4-8", "24", "None"]', 1, 'Excellent for post-op blocks. (Mont Reid Ch. 1)'),
    (v_topic_id, '166: "Tetracaine" is commonly used as a/an ____ anesthetic.', '["Intravenous", "Topical / Ophthalmic", "Muscle", "None"]', 1, 'An ester. (Schwartz''s Ch. 11)'),
    (v_topic_id, '167: "Neuromuscular Monitor" (Train of Four) measures how many ____.', '["Vitamins", "Twitches", "Seconds", "None"]', 1, 'Determines degree of paralysis. (de Virgilio Ch. 1)'),
    (v_topic_id, '168: A TOF of 0/4 twitches means:', '["Full paralysis", "No paralysis", "Half", "None"]', 0, 'Cannot be reversed yet. (Mont Reid Ch. 1)'),
    (v_topic_id, '169: Reversal should ideally occur when TOF is at least ____.', '["0/4", "2/4 or 3/4", "4/4", "None"]', 1, 'Otherwise risk of residual weakness. (Schwartz''s Ch. 11)'),
    (v_topic_id, '170: "Pseudocholinesterase deficiency" leads to prolonged paralysis after:', '["Rocuronium", "Succinylcholine", "Propofol", "None"]', 1, 'Patient cannot break down the drug. (de Virgilio Ch. 1)'),
    (v_topic_id, '171: "Mivacurium" is a non-depolarizing blocker also broken down by:', '["Liver", "Pseudocholinesterase", "Kidneys", "None"]', 1, 'Shorter acting. (Mont Reid Ch. 1)'),
    (v_topic_id, '172: "Atracurium" is broken down by "Hofmann elimination," meaning it is safe in:', '["Kids", "Liver and Renal failure", "Obese", "None"]', 1, 'Spontaneous non-enzymatic breakdown. (Schwartz''s Ch. 11)'),
    (v_topic_id, '173: "Spinal" vs "Epidural": Which has a faster onset?', '["Epidural", "Spinal", "Same", "None"]', 1, 'Directly into CSF. (de Virgilio Ch. 1)'),
    (v_topic_id, '174: "Spinal" vs "Epidural": Which requires a HIGHER dose of drug?', '["Spinal", "Epidural", "Same", "None"]', 1, 'Space is larger and further from nerves. (Mont Reid Ch. 1)'),
    (v_topic_id, '175: "Caudal Anesthesia" is a form of epidural common in:', '["Elderly", "Pediatric surgery", "Obese", "None"]', 1, 'Injected into the sacral hiatus. (Schwartz''s Ch. 11)'),
    (v_topic_id, '176: "Post-Dural Puncture Headache" occurs more often with ____ needles.', '["Large/Cutting", "Small/Pencil-point", "Curved", "None"]', 0, 'Pencil-point needles spread fibers rather than cutting them. (de Virgilio Ch. 1)'),
    (v_topic_id, '177: "Trendelenburg" position (head down) can impair ____.', '["Digestion", "Ventilation (abdominal contents push on diaphragm)", "Vision", "None"]', 1, 'Also increases intracranial pressure. (Mont Reid Ch. 1)'),
    (v_topic_id, '178: "Reverse Trendelenburg" is used for ____ surgery.', '["Pelvic", "Upper abdominal (Esophagus/Stomach)", "Leg", "None"]', 1, 'Gravity pulls bowel down. (Schwartz''s Ch. 11)'),
    (v_topic_id, '179: "Lithotomy" position (legs in stirrups) puts the patient at risk for:', '["DVT and Peroneal nerve injury", "Shoulder pain", "Cough", "None"]', 0, 'Also compartment syndrome of the legs. (de Virgilio Ch. 1)'),
    (v_topic_id, '180: "Ulnar nerve" injury in the OR is prevented by:', '["Pads under the elbows", "Arm boards at 180 degrees", "Tight straps", "None"]', 0, 'Most common perioperative nerve injury. (Mont Reid Ch. 1)'),
    (v_topic_id, '181: "Brachial plexus" injury occurs if the arm is abducted > ____ degrees.', '["30", "90", "120", "None"]', 1, 'Due to stretch. (Schwartz''s Ch. 11)'),
    (v_topic_id, '182: "Common Peroneal nerve" injury causes:', '["Wrist drop", "Foot drop", "Blindness", "None"]', 1, 'Due to pressure at the fibular head. (de Virgilio Ch. 1)'),
    (v_topic_id, '183: "Hypothermia" in the OR causes:', '["Faster healing", "Coagulopathy and increased SSI risk", "Weight loss", "None"]', 1, 'Warming blankets are standard. (Mont Reid Ch. 1)'),
    (v_topic_id, '184: "Surgical infection" risk is increased by blood transfusion.', '["True", "False", "Only in trauma", "None"]', 0, 'Immunomodulatory effect of transfusion. (Schwartz''s Ch. 4)'),
    (v_topic_id, '185: "Lavage" of the abdomen with antibiotics is ____ compared to saline.', '["Superior", "Not shown to be more effective", "Dangerous", "None"]', 1, 'Systemic antibiotics are what count. (de Virgilio Ch. 6)'),
    (v_topic_id, '186: "Wound" closure: "Staples" are faster but may be less ____ than sutures.', '["Strong", "Aesthetic", "Cheap", "None"]', 1, 'Often used for scalp or long laparotomy. (Mont Reid Ch. 1)'),
    (v_topic_id, '187: "Vertical Mattress" suture is best for ____.', '["Inversion", "Eversion of skin edges", "Muscle", "None"]', 1, '"Far-far-near-near." (Schwartz''s Ch. 11)'),
    (v_topic_id, '188: "Horizontal Mattress" is best for ____.', '["Low tension", "High tension / Hemostasis", "Bowel", "None"]', 1, 'Used in friable tissues. (de Virgilio Ch. 7)'),
    (v_topic_id, '189: "Deep Dermal" sutures reduce ____.', '["Pain", "Tension on the skin closure", "Infection", "None"]', 1, 'Ensures a thin scar. (Mont Reid Ch. 1)'),
    (v_topic_id, '190: "Subcuticular" suture is for ____.', '["Strength", "Cosmetic skin closure", "Fascia", "None"]', 1, 'Running suture just below the surface. (Schwartz''s Ch. 11)'),
    (v_topic_id, '191: "Jackson-Pratt" (JP) drain is ____ suction.', '["High", "Low / Bulb", "Gravity", "None"]', 1, 'Common for abdominal cases. (de Virgilio Ch. 7)'),
    (v_topic_id, '192: "Hemovac" drain is ____ suction.', '["Low", "High / Spring-loaded", "None", "None"]', 1, 'Often used in ortho or large flaps. (Mont Reid Ch. 1)'),
    (v_topic_id, '193: "Drains" should be removed when output is < ____ mL/day.', '["100", "30", "5", "None"]', 1, 'Standard rule for many procedures. (Schwartz''s Ch. 11)'),
    (v_topic_id, '194: "Smoking" cessation before surgery: 12-24 hours reduces ____.', '["Infection", "Carboxyhemoglobin and Nicotine levels", "Cough", "None"]', 1, 'Immediate benefit for oxygen delivery. (de Virgilio Ch. 1)'),
    (v_topic_id, '195: "Smoking" cessation: 8 weeks reduces ____.', '["Nothing", "Pulmonary complications", "Weight", "None"]', 1, 'Ciliary function recovery. (Mont Reid Ch. 1)'),
    (v_topic_id, '196: "Malnourished" patients have a ____ fold increase in mortality.', '["2", "3", "10", "None"]', 1, 'Nutritional optimization is key. (Schwartz''s Ch. 2)'),
    (v_topic_id, '197: "ERAS" goal: Reduce "length of ____."', '["Surgery", "Stay", "Incision", "None"]', 1, 'Accelerated discharge. (de Virgilio Ch. 1)'),
    (v_topic_id, '198: "Post-op" fever: "Wonder drugs" refers to ____.', '["Vitamins", "Drug fever / Heparin / Antibiotics", "Aspirin", "None"]', 1, 'Diagnosis of exclusion. (Mont Reid Ch. 1)'),
    (v_topic_id, '199: "C. diff" diarrhea post-op: First step?', '["Stool culture", "Isolation and send for C. diff toxin PCR", "Surgery", "None"]', 1, 'Contact precautions immediately. (Schwartz''s Ch. 6)'),
    (v_topic_id, '200: "Anesthesia" relates to "loss of sensation"; "Analgesia" relates to "loss of ____."', '["Memory", "Pain", "Movement", "None"]', 1, 'Key distinction. (de Virgilio Ch. 1)'),

    -- SECTION 7: Advanced Case Pearls (201-350)
    (v_topic_id, '201: "ASA IV" example = ?', '["Controlled diabetes", "Severe heart failure / Unstable angina", "Healthy smoker", "None"]', 1, 'Constant threat to life. (Schwartz''s Ch. 11)'),
    (v_topic_id, '202: "ASA V" patient = ?', '["Healthy", "Moribund / Not expected to survive 24h", "Aged > 90", "None"]', 1, 'Surgery is a last resort. (de Virgilio Ch. 1)'),
    (v_topic_id, '203: "Mallampati II" = ?', '["Only uvula tip seen", "Uvula and tonsils visible", "No uvula seen", "None"]', 1, 'Soft palate and uvula are visible. (Mont Reid Ch. 1)'),
    (v_topic_id, '204: "Sellick Maneuver" = ?', '["Head tilt", "Cricoid pressure", "Jaw thrust", "None"]', 1, 'Prevents aspiration. (Schwartz''s Ch. 11)'),
    (v_topic_id, '205: "Aspiration" classic location = ?', '["Left upper lobe", "Right lower lobe", "Both", "None"]', 1, 'Straight shot. (de Virgilio Ch. 1)'),
    (v_topic_id, '206: "Mendelson Syndrome" = ?', '["Aspiration pneumonitis", "DVT", "Bleeding", "None"]', 0, 'Chemical burn of lungs. (Mont Reid Ch. 1)'),
    (v_topic_id, '207: "TRALI" onset = ?', '["1 week", "Within 6 hours of transfusion", "POD 30", "None"]', 1, 'Acute lung injury. (Schwartz''s Ch. 4)'),
    (v_topic_id, '208: "TRALI" vs "TACO": TRALI has ____ CVP.', '["High", "Normal/Low", "Same", "None"]', 1, 'Non-cardiogenic. (de Virgilio Ch. 3)'),
    (v_topic_id, '209: "Transfusion reaction" - dark urine = ?', '["Normal", "Acute Hemolytic Reaction (Hemoglobinuria)", "Infection", "None"]', 1, 'Stop transfusion immediately. (Mont Reid Ch. 4)'),
    (v_topic_id, '210: "Clostridial" infection (POD 1) = ?', '["Group A Strep or Clostridium", "Staph", "E. coli", "None"]', 0, '"Toxic" appearance. (Schwartz''s Ch. 6)'),
    (v_topic_id, '211: "Post-op MI" peak = ?', '["POD 1", "POD 2-3", "POD 30", "None"]', 1, 'Often silent. (de Virgilio Ch. 1)'),
    (v_topic_id, '212: "Post-op Delirium" - check for ____ first.', '["Hypoxia", "Urinary retention", "Pain", "All of the above"]', 3, 'Workup for reversible causes. (Mont Reid Ch. 1)'),
    (v_topic_id, '213: "Epidural Blood Patch" = ?', '["Treats PDPH", "Treats bleeding", "Treats fever", "None"]', 0, 'Clots the leak. (Schwartz''s Ch. 11)'),
    (v_topic_id, '214: "Dantrolene" dose = ?', '["1 mg", "2.5 mg/kg (initial)", "100 mg", "None"]', 1, 'May need frequent repeat doses. (de Virgilio Ch. 1)'),
    (v_topic_id, '215: "Succinylcholine" K+ rise = ?', '["0.5 - 1.0 mEq/L", "5.0", "None", "None"]', 0, 'Normal response. (Mont Reid Ch. 1)'),
    (v_topic_id, '216: "Succinylcholine" in burns = ?', '["Safe", "Strictly Contraindicated after 24-48h", "Preferred", "None"]', 1, 'Massive K+ release due to up-regulated receptors. (Schwartz''s Ch. 11)'),
    (v_topic_id, '217: "Sugammadex" works on ____.', '["Succinylcholine", "Aminosteroid blockers (Roc/Vec)", "Benzylisoquinolines", "None"]', 1, 'Direct binding. (de Virgilio Ch. 1)'),
    (v_topic_id, '218: "Metoclopramide" EPS risk = ?', '["None", "Tardive Dyskinesia", "Weight gain", "None"]', 1, 'Dopamine block. (Mont Reid Ch. 1)'),
    (v_topic_id, '219: "Ketorolac" POD limit = ?', '["1 day", "5 days", "30 days", "None"]', 1, 'Risk of GI bleed / Renal failure. (Schwartz''s Ch. 11)'),
    (v_topic_id, '220: "Spinal" block: "High Spinal" = ?', '["Headache only", "Respiratory distress / Bradycardia", "Fever", "None"]', 1, 'Sympathetic block. (de Virgilio Ch. 1)'),
    (v_topic_id, '221: "Local anesthetic" - metallic taste = ?', '["Normal", "Sign of toxicity (LAST)", "Allergy", "None"]', 1, 'CNS sign. (Mont Reid Ch. 1)'),
    (v_topic_id, '222: "LAST" treatment = ?', '["Oxygen", "Intralipid (Lipid Rescue)", "Heparin", "None"]', 1, 'Standard of care. (Schwartz''s Ch. 11)'),
    (v_topic_id, '223: "PONV" - most common risk factor = ?', '["Old age", "Female gender", "Smoking", "None"]', 1, 'Strongest predictor. (de Virgilio Ch. 1)'),
